document.addEventListener("DOMContentLoaded",function(){const menuToggle=document.getElementById("menuToggle");const mobileMenu=document.getElementById("mobileMenu");const menuOverlay=document.getElementById("menuOverlay");const navLinks=document.querySelectorAll(".navigation-link");function openMenu(){menuToggle.classList.add("active");mobileMenu.classList.add("active");menuOverlay.classList.add("active");document.body.classList.add("menu-open");menuToggle.setAttribute("aria-expanded","true");}function closeMenu(){menuToggle.classList.remove("active");mobileMenu.classList.remove("active");menuOverlay.classList.remove("active");document.body.classList.remove("menu-open");menuToggle.setAttribute("aria-expanded","false");}if(!menuToggle||!mobileMenu||!menuOverlay){return;}menuToggle.setAttribute("aria-expanded","false");menuToggle.addEventListener("click",function(){if(mobileMenu.classList.contains("active")){closeMenu();}else{openMenu();}});menuOverlay.addEventListener("click",closeMenu);navLinks.forEach(function(link){link.addEventListener("click",closeMenu);});window.addEventListener("resize",function(){if(window.innerWidth>991){closeMenu();}});document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeMenu();}});});(function(){const slides=document.querySelectorAll("#featureRight .slide");const dots=document.querySelectorAll("#slideDots button");const prevBtn=document.getElementById("prevBtn");const nextBtn=document.getElementById("nextBtn");if(slides.length===0||dots.length===0||!prevBtn||!nextBtn){return;}let current=0;let autoplayId;function goTo(index){slides[current].classList.remove("active");dots[current].classList.remove("active");current=(index+slides.length)% slides.length;slides[current].classList.add("active");dots[current].classList.add("active");}function next(){goTo(current+1);}function prev(){goTo(current-1);}nextBtn.addEventListener("click",function(){next();resetAutoplay();});prevBtn.addEventListener("click",function(){prev();resetAutoplay();});dots.forEach(function(dot){dot.addEventListener("click",function(){const index=parseInt(dot.dataset.index,10);goTo(index);resetAutoplay();});});function startAutoplay(){autoplayId=setInterval(function(){next();},5000);}function resetAutoplay(){clearInterval(autoplayId);startAutoplay();}startAutoplay();})();document.addEventListener("DOMContentLoaded",function(){const faqItems=document.querySelectorAll(".faq-item");if(!faqItems.length){return;}faqItems.forEach(function(item){const question=item.querySelector(".faq-question");const answer=item.querySelector(".faq-answer");const icon=item.querySelector(".faq-icon");if(!question||!answer||!icon){return;}if(item.classList.contains("active")){answer.style.maxHeight=answer.scrollHeight+"px";question.setAttribute("aria-expanded","true");icon.textContent="−";}else{answer.style.maxHeight="0px";question.setAttribute("aria-expanded","false");icon.textContent="+";}});faqItems.forEach(function(item){const question=item.querySelector(".faq-question");const answer=item.querySelector(".faq-answer");const icon=item.querySelector(".faq-icon");if(!question||!answer||!icon){return;}question.addEventListener("click",function(){const isOpen=item.classList.contains("active");faqItems.forEach(function(otherItem){if(otherItem===item){return;}const otherQuestion=otherItem.querySelector(".faq-question");const otherAnswer=otherItem.querySelector(".faq-answer");const otherIcon=otherItem.querySelector(".faq-icon");if(!otherQuestion||!otherAnswer||!otherIcon){return;}otherItem.classList.remove("active");otherAnswer.style.maxHeight="0px";otherQuestion.setAttribute("aria-expanded","false");otherIcon.textContent="+";});if(isOpen){item.classList.remove("active");answer.style.maxHeight="0px";question.setAttribute("aria-expanded","false");icon.textContent="+";}else{item.classList.add("active");answer.style.maxHeight=answer.scrollHeight+"px";question.setAttribute("aria-expanded","true");icon.textContent="−";}});});window.addEventListener("resize",function(){faqItems.forEach(function(item){if(!item.classList.contains("active")){return;}const answer=item.querySelector(".faq-answer");if(answer){answer.style.maxHeight=answer.scrollHeight+"px";}});});});document.addEventListener("DOMContentLoaded",function(){let currentPage=window.location.pathname.split("/").pop();if(currentPage===""){currentPage="index.html";}const navigationLinks=document.querySelectorAll(".navigation-link");navigationLinks.forEach(function(link){const linkPage=link.getAttribute("href").split("/").pop();if(linkPage===currentPage){link.classList.add("active");}else{link.classList.remove("active");}});const footerLinks=document.querySelectorAll(".footer-link");footerLinks.forEach(function(link){const linkPage=link.getAttribute("href").split("/").pop();if(linkPage===currentPage){link.classList.add("active");}else{link.classList.remove("active");}});});document.addEventListener("DOMContentLoaded",function(){const filterButtons=document.querySelectorAll(".dl-filter-btn");const featureCards=document.querySelectorAll(".dl-feature-card");filterButtons.forEach(function(button){button.addEventListener("click",function(){const selectedFilter=button.dataset.filter;filterButtons.forEach(function(filterButton){const isActive=filterButton===button;filterButton.classList.toggle("is-active",isActive);filterButton.setAttribute("aria-pressed",String(isActive));});featureCards.forEach(function(card){const categories=(card.dataset.category||"").split(/\s+/);const shouldShow=selectedFilter==="all"||categories.includes(selectedFilter);card.classList.toggle("is-hidden",!shouldShow);if(shouldShow){card.classList.remove("is-entering");void card.offsetWidth;card.classList.add("is-entering");}});});});filterButtons.forEach(function(button){button.setAttribute("aria-pressed",String(button.classList.contains("is-active")));});});
